from decimal import Decimal


def _line_number_key(value: object) -> tuple[int, Decimal]:
    """Return a numeric sort key, placing missing values before numbered rows."""
    if value == "":
        return (0, Decimal(0))
    return (1, Decimal(str(value).strip()))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove deleted order lines and renumber surviving lines per order."""
    sortable: list[tuple[str, tuple[int, Decimal], dict]] = []

    for row in lines:
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        line_key = _line_number_key(row.get("LINE_NO", ""))
        sortable.append((order_id, line_key, row))

    sortable.sort(key=lambda item: (item[0], item[1]))

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for order_id, _, row in sortable:
        if order_id != current_order:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        copied = dict(row)
        copied["LINE_NO"] = next_line_no
        result.append(copied)

    return result
